dtsPropsFor.Title:
/** Title text (Playfair, weight 800). */
children?: React.ReactNode;
/** Italic tail in verde-medio — the signature gesture. */
flourish?: string;

dtsPropsFor.Logo:
/** Pick by background: dark bg -> crema/white, light bg -> verde/black. */
variant?: 'verde' | 'crema' | 'white' | 'black';
/** Render width in px. Min ~120px; below that use the O isotype instead. */
width?: number;
style?: React.CSSProperties;

dtsPropsFor.Flor:
/** 'botanica' = lila bell + leaves (small accent); 'grande' = symmetric 4-petal silhouette (huge / full-bleed). */
kind?: 'botanica' | 'grande';
/** Only applies to kind="grande" — follow the background. */
fill?: 'crema' | 'verde' | 'lila';
width?: number;
opacity?: number;
style?: React.CSSProperties;

dtsPropsFor.Card:
/** Uppercase Poppins kicker at the top of the card. */
title?: string;
/** light = white/crema, dark = panel, green = verde accent. */
tone?: 'light' | 'dark' | 'green';
children?: React.ReactNode;

dtsPropsFor.Pill:
children?: React.ReactNode;
/** verde-medio by default; lila as an occasional spark. */
tone?: 'verde' | 'lila';

dtsPropsFor.Button:
children?: React.ReactNode;
/** primary = verde on crema; inverse = crema on verde; ghost = outlined. */
variant?: 'primary' | 'inverse' | 'ghost';
onClick?: React.MouseEventHandler<HTMLButtonElement>;
disabled?: boolean;
type?: 'button' | 'submit' | 'reset';
style?: React.CSSProperties;

dtsPropsFor.Statement:
/** Small Poppins kicker (verde). */
eyebrow?: string;
/** Main line (Playfair, white). */
headline?: string;
/** Italic tail in verde-medio — the signature gesture. */
flourish?: string;
/** One or two short lines. */
body?: string;
